// Chunk article content for embedding
const CHUNK_SIZE = 500;
const CHUNK_OVERLAP = 50;

const articles = $input.all().map(i => i.json);
const allChunks = [];

for (const article of articles) {
  const text = article.content || article.summary || '';
  if (text.length < 50) continue;

  // Sentence-based chunking
  const sentences = text.match(/[^.!?\n]+[.!?\n]*/g) || [text];
  let currentChunk = '';
  let chunkIndex = 0;

  for (const sentence of sentences) {
    const trimmed = sentence.trim();
    if (!trimmed) continue;

    if (currentChunk.length + trimmed.length > CHUNK_SIZE && currentChunk.length > 0) {
      allChunks.push({
        json: {
          pointId: article.id * 10000 + chunkIndex,
          articleId: article.id,
          chunkIndex,
          chunkText: currentChunk.trim(),
          textForEmbedding: article.title + '\n\n' + currentChunk.trim(),
          title: article.title,
          source: article.source,
          category: article.category,
          published_at: article.published_at,
          url: article.url
        }
      });
      chunkIndex++;
      const overlap = currentChunk.slice(-CHUNK_OVERLAP);
      currentChunk = overlap + ' ' + trimmed;
    } else {
      currentChunk += (currentChunk ? ' ' : '') + trimmed;
    }
  }

  if (currentChunk.trim()) {
    allChunks.push({
      json: {
        pointId: article.id * 10000 + chunkIndex,
        articleId: article.id,
        chunkIndex,
        chunkText: currentChunk.trim(),
        textForEmbedding: article.title + '\n\n' + currentChunk.trim(),
        title: article.title,
        source: article.source,
        category: article.category,
        published_at: article.published_at,
        url: article.url
      }
    });
  }
}

return allChunks;
